package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__deserializeWithNativeTypeId_TriageGen0Test {

    private TestableTypeDeserializer sut;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private JavaType mockBaseType;
    private TypeIdResolver mockIdResolver;

    // Concrete implementation to access protected method and mock internal calls
    private static class TestableTypeDeserializer extends TypeDeserializerBase {
        private JsonDeserializer<Object> mockDefaultDeserializer;
        private JsonDeserializer<Object> mockSpecificDeserializer;
        private boolean throwMappingExceptionOnNullDefault = false;

        protected TestableTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, boolean typeIdVisible, Class<?> defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        @Override
        public TypeDeserializer forProperty(com.fasterxml.jackson.databind.BeanProperty prop) {
            return null;
        }

        @Override
        public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() {
            return null;
        }

        @Override
        public String baseTypeName() {
            return "TestBase";
        }

        @Override
        protected final JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return mockSpecificDeserializer;
        }

        @Override
        protected final JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            if (throwMappingExceptionOnNullDefault && mockDefaultDeserializer == null) {
                throw ctxt.mappingException("No (native) type id found when one was expected for polymorphic type handling");
            }
            return mockDefaultDeserializer;
        }

        // Expose the protected method for testing
        @Override
        public Object _deserializeWithNativeTypeId(JsonParser jp, DeserializationContext ctxt, Object typeId) throws IOException {
            return super._deserializeWithNativeTypeId(jp, ctxt, typeId);
        }
    }

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockBaseType = mock(JavaType.class);
        mockIdResolver = mock(TypeIdResolver.class);
        sut = new TestableTypeDeserializer(mockBaseType, mockIdResolver, "type", true, null);
    }

    @Test
    public void testDeserializeWithNullTypeId_Success() throws IOException {
        // Arrange
        Object expectedResult = new Object();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenReturn(expectedResult);
        sut.mockDefaultDeserializer = mockDeser;

        // Act
        Object actualResult = sut._deserializeWithNativeTypeId(mockParser, mockContext, null);

        // Assert
        assertEquals(expectedResult, actualResult);
        verify(mockDeser).deserialize(mockParser, mockContext);
    }

    @Test(expected = RuntimeException.class)
    public void testDeserializeWithNullTypeId_ThrowsMappingException() throws IOException {
        // Arrange
        sut.throwMappingExceptionOnNullDefault = true;
        sut.mockDefaultDeserializer = null;
        when(mockContext.mappingException(anyString())).thenThrow(new RuntimeException("Mapping Exception"));

        // Act
        sut._deserializeWithNativeTypeId(mockParser, mockContext, null);
    }

    @Test
    public void testDeserializeWithStringTypeId_Success() throws IOException {
        // Arrange
        String typeId = "MyType";
        Object expectedResult = new Object();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenReturn(expectedResult);
        sut.mockSpecificDeserializer = mockDeser;

        // Act
        Object actualResult = sut._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        // Assert
        assertEquals(expectedResult, actualResult);
        verify(mockDeser).deserialize(mockParser, mockContext);
    }

    @Test
    public void testDeserializeWithNonStringTypeId_Success() throws IOException {
        // Arrange
        Integer typeIdInt = 123;
        String expectedTypeIdStr = "123";
        Object expectedResult = new Object();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenReturn(expectedResult);
        sut.mockSpecificDeserializer = mockDeser;

        // Act
        Object actualResult = sut._deserializeWithNativeTypeId(mockParser, mockContext, typeIdInt);

        // Assert
        assertEquals(expectedResult, actualResult);
        // We can't easily verify internal _findDeserializer call arguments directly without spying, 
        // but we ensure the logic flows through the String.valueOf conversion.
    }

    @Test
    public void testDeserializeWithNullTypeId_WhenDefaultDeserializerIsFound() throws IOException {
        // Arrange
        Object expectedResult = "DefaultValue";
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(eq(mockParser), eq(mockContext))).thenReturn(expectedResult);
        sut.mockDefaultDeserializer = mockDeser;

        // Act
        Object actualResult = sut._deserializeWithNativeTypeId(mockParser, mockContext, null);

        // Assert
        assertEquals(expectedResult, actualResult);
    }
}
